// Independent brute-force reference: scan every prefix for every query.
#include <arpa/inet.h>
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
int main(int argc, char** argv) {
    if (argc != 3) { fprintf(stderr, "ref FIB TRACE\n"); return 9; }
    FILE* f = fopen(argv[1], "r");
    if (!f) { fprintf(stderr, "open fib\n"); return 9; }
    std::vector<unsigned char> addr; std::vector<uint32_t> plen, hop;
    char line[4096];
    while (fgets(line, sizeof line, f)) {
        char a[512]; int L; unsigned long long H;
        if (sscanf(line, " %511[^/]/%d %llu", a, &L, &H) != 3) continue;
        unsigned char b[16];
        if (inet_pton(AF_INET6, a, b) != 1) { fprintf(stderr, "bad addr %s\n", a); return 9; }
        for (int i = 0; i < 16; ++i) addr.push_back(b[i]);
        plen.push_back((uint32_t)L); hop.push_back((uint32_t)H);
    }
    fclose(f);
    FILE* t = fopen(argv[2], "r");
    if (!t) { fprintf(stderr, "open trace\n"); return 9; }
    size_t n = plen.size();
    while (fgets(line, sizeof line, t)) {
        char a[512];
        if (sscanf(line, " %511s", a) != 1) continue;
        unsigned char b[16];
        if (inet_pton(AF_INET6, a, b) != 1) { fprintf(stderr, "bad addr\n"); return 9; }
        uint64_t k = 0; for (int i = 0; i < 8; ++i) k = (k << 8) | b[i];
        uint64_t lo = 0, hi = 0;
        for (int i = 7; i < 16; ++i) { lo = (lo << 8) | b[i]; }
        (void)hi;
        int bestlen = -1; uint32_t besthop = 0;
        for (size_t i = 0; i < n; ++i) {
            uint64_t pk = 0;
            for (int j = 0; j < 8; ++j) pk = (pk << 8) | addr[i * 16 + j];
            uint32_t L = plen[i];
            uint64_t mask = L == 0 ? 0 : (~0ULL) << (64 - L);
            if ((k & mask) == pk && (int)L > bestlen) { bestlen = (int)L; besthop = hop[i]; }
        }
        if (bestlen < 0) printf("-1 -1\n"); else printf("%u %d\n", besthop, bestlen);
    }
    fclose(t);
    return 0;
}
EOF
g++ -O2 -o /work/tests/ref /work/tests/ref.cpp && echo built
